-- Trigger for qrtz_blob_triggers_ibfk_1 (ON DELETE RESTRICT)
-- Prevents deletion of QRTZ_TRIGGERS if child records exist in QRTZ_BLOB_TRIGGERS
DELIMITER //

DROP TRIGGER IF EXISTS `trg_QRTZ_BLOB_TRIGGERS_before_delete_qrtz_blob_triggers_i` //

CREATE TRIGGER `trg_QRTZ_BLOB_TRIGGERS_before_delete_qrtz_blob_triggers_i`
BEFORE DELETE ON `QRTZ_TRIGGERS`
FOR EACH ROW
BEGIN
    DECLARE error_msg VARCHAR(255);
    
    IF EXISTS (
        SELECT 1 FROM `QRTZ_BLOB_TRIGGERS`
        WHERE `SCHED_NAME` = OLD.`SCHED_NAME` AND `TRIGGER_NAME` = OLD.`TRIGGER_NAME` AND `TRIGGER_GROUP` = OLD.`TRIGGER_GROUP`
    ) THEN
        SET error_msg = CONCAT(
            'Cannot delete from QRTZ_TRIGGERS because records exist in QRTZ_BLOB_TRIGGERS ',
            'with constraint qrtz_blob_triggers_ibfk_1'
        );
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = error_msg;
    END IF;
END //

