DELIMITER //

DROP TRIGGER IF EXISTS `trg_tblProject_before_delete_fk_tblProject_tblAss` //

CREATE TRIGGER `trg_tblProject_before_delete_fk_tblProject_tblAss`
BEFORE DELETE ON `tblAsset`
FOR EACH ROW
BEGIN
    DECLARE error_msg VARCHAR(255);
    
    IF EXISTS (
        SELECT 1 FROM `tblProject`
        WHERE `intTenantID` = OLD.`intTenantID` AND `intSiteID` = OLD.`id`
    ) THEN
        SET error_msg = CONCAT(
            'Cannot delete from tblAsset because records exist in tblProject ',
            'with constraint fk_tblProject_tblAsset_1070'
        );
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = error_msg;
    END IF;
END //

